# ads1x15_reading_table_format.py
# Reads analog inputs from an ADS1x15 ADC and prints a table of values.
# Optimized for Raspberry Pi Zero W classroom demonstration.

import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

def initialize_i2c_bus():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus, address=0x48, gain=1):
    """Initializes the ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus, address=address, gain=gain)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def read_adc_channels(adc_device):
    """Reads all four ADC channels."""
    try:
        channel_a = AnalogIn(adc_device, ADS.P0)
        channel_b = AnalogIn(adc_device, ADS.P1)
        channel_c = AnalogIn(adc_device, ADS.P2)
        channel_d = AnalogIn(adc_device, ADS.P3)
        return channel_a, channel_b, channel_c, channel_d
    except Exception as e:
        print(f"Error reading ADC channels: {e}")
        return None

def print_header():
    """Prints the table header."""
    print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format("Ch0", "Ch1", "Ch2", "Ch3"))
    print("-" * 37)

def print_channel_values(channel_a, channel_b, channel_c, channel_d):
    """Prints the ADC channel values."""
    try:
        print("| {0:>6} | {1:>6} | {2:>6} | {3:>6} |".format(
            channel_a.value, channel_b.value, channel_c.value, channel_d.value))
    except Exception as e:
        print(f"Error printing channel values: {e}")

def main():
    """Main function to read and print ADC values."""
    i2c_bus = initialize_i2c_bus()
    if i2c_bus is None:
        return

    adc_device = initialize_adc(i2c_bus)
    if adc_device is None:
        return

    print_header()

    try:
        while True:
            adc_channels = read_adc_channels(adc_device)
            if adc_channels:
                channel_a, channel_b, channel_c, channel_d = adc_channels
                print_channel_values(channel_a, channel_b, channel_c, channel_d)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        # No specific cleanup needed for I2C or ADC in this library
        print("Program finished.")

if __name__ == "__main__":
    main()

