#!/usr/bin/env python3

import RPi.GPIO as GPIO
import spidev
import time
import datetime
import logging
import json
import urllib.request
import urllib.error
import signal
import sys
from picamera import PiCamera

# Configuration
CONFIG_FILE = "config.json"
LOG_FILE = "irrigation.log"
DEFAULT_IRRIGATION_DURATION = 600  # 10 minutes in seconds
DEFAULT_CHECK_INTERVAL = 300  # 5 minutes in seconds
DEFAULT_RAINFALL_THRESHOLD = 2  # mm
DEFAULT_CAMERA_CAPTURE_INTERVAL = 600 # 10 minutes in seconds
DEFAULT_SPI_SPEED = 1000000 # 1 MHz

# Global variables
spi = None
camera = None
running = True
valve_states = [False, False, False, False] # Track valve states

# Custom Exception Classes
class ConfigurationError(Exception):
    pass

class SPICommunicationError(Exception):
    pass

class CameraError(Exception):
    pass

class WeatherDataError(Exception):
    pass

# Configuration Management Functions
def load_config(config_file):
    """Loads configuration from a JSON file."""
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        return config
    except FileNotFoundError:
        logging.error(f"Configuration file not found: {config_file}")
        raise ConfigurationError("Configuration file not found.")
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in configuration file: {config_file}")
        raise ConfigurationError("Invalid JSON format in configuration file.")
    except Exception as e:
        logging.error(f"Error loading configuration: {e}")
        raise ConfigurationError(f"Error loading configuration: {e}")

def validate_config(config):
    """Validates the configuration data."""
    if not isinstance(config, dict):
        raise ConfigurationError("Configuration must be a dictionary.")

    required_keys = ["valve_pins", "adc_channels", "soil_moisture_thresholds", "rainfall_threshold", "irrigation_duration", "check_interval", "camera_capture_interval", "weather_api_key", "weather_location"]
    for key in required_keys:
        if key not in config:
            raise ConfigurationError(f"Missing configuration key: {key}")

    if not isinstance(config["valve_pins"], list) or len(config["valve_pins"]) != 4:
        raise ConfigurationError("Valve pins must be a list of 4 integers.")
    if not all(isinstance(pin, int) for pin in config["valve_pins"]):
        raise ConfigurationError("Valve pins must be integers.")

    if not isinstance(config["adc_channels"], list) or len(config["adc_channels"]) != 4:
        raise ConfigurationError("ADC channels must be a list of 4 integers.")
    if not all(isinstance(channel, int) for channel in config["adc_channels"]):
        raise ConfigurationError("ADC channels must be integers.")

    if not isinstance(config["soil_moisture_thresholds"], list) or len(config["soil_moisture_thresholds"]) != 4:
        raise ConfigurationError("Soil moisture thresholds must be a list of 4 integers.")
    if not all(isinstance(threshold, int) for threshold in config["soil_moisture_thresholds"]):
        raise ConfigurationError("Soil moisture thresholds must be integers.")

    if not isinstance(config["rainfall_threshold"], (int, float)):
        raise ConfigurationError("Rainfall threshold must be a number.")

    if not isinstance(config["irrigation_duration"], int):
        raise ConfigurationError("Irrigation duration must be an integer.")

    if not isinstance(config["check_interval"], int):
        raise ConfigurationError("Check interval must be an integer.")

    if not isinstance(config["camera_capture_interval"], int):
        raise ConfigurationError("Camera capture interval must be an integer.")

    if not isinstance(config["weather_api_key"], str):
        raise ConfigurationError("Weather API key must be a string.")

    if not isinstance(config["weather_location"], str):
        raise ConfigurationError("Weather location must be a string.")

# Modular Subsystem Functions
def read_mcp3008(channel):
    """Reads data from the MCP3008 ADC."""
    try:
        # MCP3008 requires a start bit (1), single-ended bit (1), and channel selection bits (3)
        adc_command = [1, (8 + channel) << 4, 0]
        response = spi.xfer2(adc_command)

        # Extract the 10 bits of data from the response
        adc_value = ((response[1] & 3) << 8) + response[2]
        return adc_value
    except Exception as e:
        logging.error(f"SPI communication error: {e}")
        raise SPICommunicationError(f"SPI communication error: {e}")

def control_valve(valve_number, state):
    """Controls a single irrigation valve."""
    try:
        if valve_number < 1 or valve_number > 4:
            raise ValueError("Valve number must be between 1 and 4")

        pin = config["valve_pins"][valve_number - 1]
        GPIO.output(pin, state)
        valve_states[valve_number - 1] = state # Update valve state
        logging.info(f"Valve {valve_number} turned {'ON' if state else 'OFF'}")
    except ValueError as e:
        logging.error(f"Invalid valve number: {e}")
    except Exception as e:
        logging.error(f"Error controlling valve {valve_number}: {e}")

def check_weather(weather_api_key, weather_location):
    """Checks weather data from OpenWeatherMap API."""
    try:
        api_url = f"http://api.openweathermap.org/data/2.5/weather?q={weather_location}&appid={weather_api_key}"
        with urllib.request.urlopen(api_url) as response:
            data = json.loads(response.read().decode())
            rain = data.get("rain", {}).get("1h", 0)  # Get rain in the last hour (1h)
            return rain
    except urllib.error.URLError as e:
        logging.error(f"Network error fetching weather data: {e}")
        raise WeatherDataError(f"Network error fetching weather data: {e}")
    except json.JSONDecodeError as e:
        logging.error(f"Error decoding JSON from weather API: {e}")
        raise WeatherDataError(f"Error decoding JSON from weather API: {e}")
    except Exception as e:
        logging.error(f"Error fetching weather data: {e}")
        raise WeatherDataError(f"Error fetching weather data: {e}")

def capture_image():
    """Captures an image using the Raspberry Pi camera."""
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        image_path = f"image_{timestamp}.jpg"
        camera.capture(image_path)
        logging.info(f"Image captured: {image_path}")
        return image_path
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        raise CameraError(f"Error capturing image: {e}")

# Resource Management Functions
def initialize_gpio(valve_pins):
    """Initializes GPIO pins for the irrigation valves."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in valve_pins:
            GPIO.setup(pin, GPIO.OUT)
            GPIO.output(pin, GPIO.LOW)  # Initialize all valves to OFF
        logging.info("GPIO pins initialized for irrigation valves.")
    except Exception as e:
        logging.error(f"Error initializing GPIO pins: {e}")
        raise

def initialize_spi(spi_speed):
    """Initializes the SPI interface."""
    try:
        global spi
        spi = spidev.SpiDev()
        spi.open(0, 0)  # Bus 0, Chip Select 0 (CE0)
        spi.max_speed_hz = spi_speed
        logging.info("SPI interface initialized.")
    except Exception as e:
        logging.error(f"Error initializing SPI interface: {e}")
        raise

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        global camera
        camera = PiCamera()
        camera.resolution = (640, 480) # Set a reasonable resolution
        camera.rotation = 0 # Adjust as needed
        logging.info("Camera initialized.")
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        raise

def cleanup_gpio(valve_pins):
    """Cleans up GPIO pins."""
    try:
        for pin in valve_pins:
            GPIO.output(pin, GPIO.LOW)  # Turn off all valves
        GPIO.cleanup()
        logging.info("GPIO pins cleaned up.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO pins: {e}")

def close_spi():
    """Closes the SPI interface."""
    try:
        if spi:
            spi.close()
            logging.info("SPI interface closed.")
    except Exception as e:
        logging.error(f"Error closing SPI interface: {e}")

def close_camera():
    """Closes the camera."""
    try:
        if camera:
            camera.close()
            logging.info("Camera closed.")
    except Exception as e:
        logging.error(f"Error closing camera: {e}")

# Signal Handlers
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global running
    logging.info(f"Received signal {sig}. Shutting down...")
    running = False

# Logging Configuration
def setup_logging(log_file):
    """Sets up logging to a file."""
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )
    # Also log to console
    console = logging.StreamHandler()
    console.setLevel(logging.INFO)
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    console.setFormatter(formatter)
    logging.getLogger('').addHandler(console)

# Main Program Orchestration
def main():
    """Main function to orchestrate the irrigation system."""
    global config, running

    try:
        setup_logging(LOG_FILE)
        config = load_config(CONFIG_FILE)
        validate_config(config)

        initialize_gpio(config["valve_pins"])
        initialize_spi(config["spi_speed"])
        initialize_camera()

        logging.info("Irrigation system started.")

        last_camera_capture = time.time()

        while running:
            try:
                for i in range(4):
                    adc_channel = config["adc_channels"][i]
                    soil_moisture_threshold = config["soil_moisture_thresholds"][i]
                    irrigation_duration = config["irrigation_duration"]

                    try:
                        adc_value = read_mcp3008(adc_channel)
                        moisture_percentage = (adc_value / 1023.0) * 100.0
                        logging.info(f"Zone {i+1}: ADC Value = {adc_value}, Moisture = {moisture_percentage:.2f}%")

                        if moisture_percentage < soil_moisture_threshold:
                            logging.info(f"Zone {i+1}: Moisture below threshold. Checking weather...")
                            try:
                                rain = check_weather(config["weather_api_key"], config["weather_location"])
                                if rain > config["rainfall_threshold"]:
                                    logging.warning(f"Zone {i+1}: Rain detected. Skipping irrigation.")
                                    continue  # Skip irrigation for this zone

                                logging.info(f"Zone {i+1}: Moisture below threshold and no rain. Irrigating for {irrigation_duration} seconds.")
                                control_valve(i + 1, GPIO.HIGH)  # Turn on valve
                                time.sleep(irrigation_duration)
                                control_valve(i + 1, GPIO.LOW)  # Turn off valve
                                logging.info(f"Zone {i+1}: Irrigation complete.")

                            except WeatherDataError as e:
                                logging.warning(f"Zone {i+1}: Weather check failed. Skipping irrigation: {e}")
                                continue  # Skip irrigation for this zone

                        else:
                            logging.info(f"Zone {i+1}: Moisture above threshold. No irrigation needed.")

                    except SPICommunicationError as e:
                        logging.error(f"Zone {i+1}: SPI communication failed. Skipping irrigation: {e}")
                        continue  # Skip irrigation for this zone
                    except Exception as e:
                        logging.error(f"Zone {i+1}: An unexpected error occurred: {e}")
                        continue  # Skip irrigation for this zone

                # Camera capture logic
                if time.time() - last_camera_capture >= config["camera_capture_interval"]:
                    try:
                        capture_image()
                        last_camera_capture = time.time()
                    except CameraError as e:
                        logging.error(f"Camera capture failed: {e}")

                time.sleep(config["check_interval"])

            except Exception as e:
                logging.error(f"An unexpected error occurred in the main loop: {e}")
                time.sleep(60) # Wait before retrying

    except ConfigurationError as e:
        logging.error(f"Configuration error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Shutting down irrigation system...")
        # Ensure all valves are turned off
        for i in range(4):
            control_valve(i + 1, GPIO.LOW)
        cleanup_gpio(config["valve_pins"])
        close_spi()
        close_camera()
        logging.info("Irrigation system stopped.")

# Entry Point
if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

