                        logging.info(f"Zone {i+1}: ADC Value = {adc_value}, Moisture = {moisture_percentage:.2f}%")

                        if moisture_percentage < soil_moisture_threshold:
                            logging.info(f"Zone {i+1}: Moisture below threshold. Checking weather...")
                            try:
                                rain = check_weather(config["weather_api_key"], config["weather_location"])
                                if rain > config["rainfall_threshold"]:
                                    logging.warning(f"Zone {i+1}: Rain detected. Skipping irrigation.")
                                    continue  # Skip irrigation for this zone

                                logging.info(f"Zone {i+1}: Moisture below threshold and no rain. Irrigating for {irrigation_duration} seconds.")
                                control_valve(i + 1, GPIO.HIGH)  # Turn on valve
                                time.sleep(irrigation_duration)
                                control_valve(i + 1, GPIO.LOW)  # Turn off valve
                                logging.info(f"Zone {i+1}: Irrigation complete.")

                            except WeatherDataError as e:
                                logging.warning(f"Zone {i+1}: Weather check failed. Skipping irrigation: {e}")
                                continue  # Skip irrigation for this zone

                        else:
                            logging.info(f"Zone {i+1}: Moisture above threshold. No irrigation needed.")

                    except SPICommunicationError as e:
                        logging.error(f"Zone {i+1}: SPI communication failed. Skipping irrigation: {e}")
                        continue  # Skip irrigation for this zone
                    except Exception as e:
                        logging.error(f"Zone {i+1}: An unexpected error occurred: {e}")
                        continue  # Skip irrigation for this zone

                # Camera capture logic
                if time.time() - last_camera_capture >= config["camera_capture_interval"]:
                    try:
                        capture_image()
                        last_camera_capture = time.time()
                    except CameraError as e:
                        logging.error(f"Camera capture failed: {e}")

                time.sleep(config["check_interval"])

            except Exception as e:
                logging.error(f"An unexpected error occurred in the main loop: {e}")
                time.sleep(60) # Wait before retrying

    except ConfigurationError as e:
        logging.error(f"Configuration error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Shutting down irrigation system...")
        # Ensure all valves are turned off
        for i in range(4):
            control_valve(i + 1, GPIO.LOW)
        cleanup_gpio(config["valve_pins"])
        close_spi()
