INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]

# Global variable to track the state of the output
output_state = False

def setup_gpio():
    """Set up GPIO pins for input and output."""
    try:
        GPIO.setmode(GPIO.BCM)
        # Set input pins with pull-up resistors
        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        # Set output pins
        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT)
            GPIO.output(pin, GPIO.LOW)  # Initialize to LOW
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        sys.exit(1)

def handle_input(channel):
    """Callback function for input pins."""
    global output_state
    try:
        if GPIO.input(4) == GPIO.LOW:
            GPIO.output(23, GPIO.HIGH)
        elif GPIO.input(5) == GPIO.LOW:
            GPIO.output(23, GPIO.LOW)
        elif GPIO.input(6) == GPIO.LOW:
            output_state = not output_state
            GPIO.output(24, GPIO.HIGH if output_state else GPIO.LOW)
            time.sleep(0.1)  # Debounce delay
            GPIO.output(24, GPIO.LOW) # Ensure output is reset after debounce
    except Exception as e:
        print(f"Error handling input: {e}")

def signal_handler(sig, frame):
    """Handle Ctrl+C gracefully."""
    print("Exiting program...")
    GPIO.cleanup()
    sys.exit(0)

def main():
    """Main function to run the program."""
    setup_gpio()

    # Set up event detection for input pins
    for pin in INPUT_PINS:
        GPIO.add_event_detect(pin, GPIO.FALLING, callback=handle_input, bouncetime=200)

    # Set up signal handler for Ctrl+C
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            time.sleep(0.1)  # Keep the main thread alive
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

