import cv2
import sys
import logging
import numpy as np
import contextlib

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
CASCADE_CLASSIFIER_PATH = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
WINDOW_NAME = 'Real-time Face Detection'
RECTANGLE_COLOR = (255, 0, 0)  # Blue in BGR
RECTANGLE_THICKNESS = 2
SCALE_FACTOR = 1.1
MIN_NEIGHBORS = 5
EXIT_KEY = 'q'

@contextlib.contextmanager
def open_camera(camera_index=0):
    """Context manager for opening and releasing the camera."""
    try:
        camera = cv2.VideoCapture(camera_index)
        if not camera.isOpened():
            raise IOError(f"Cannot open camera at index {camera_index}")
        yield camera
    except IOError as e:
        logging.error(f"Camera error: {e}")
        raise
    finally:
        if 'camera' in locals():
            camera.release()

def load_cascade_classifier(classifier_path):
    """Loads the face detection cascade classifier."""
    try:
        classifier = cv2.CascadeClassifier(classifier_path)
        if classifier.empty():
            raise IOError(f"Unable to load cascade classifier from {classifier_path}")
        return classifier
    except IOError as e:
        logging.error(f"Cascade classifier error: {e}")
        raise

def detect_faces(image, classifier, scale_factor, min_neighbors, min_size):
    """Detects faces in the given image using the provided classifier."""
    return classifier.detectMultiScale(image, scale_factor, min_neighbors, minSize=min_size)

def draw_rectangles(image, faces, color, thickness):
    """Draws rectangles around the detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(image, (x, y), (x + w, y + h), color, thickness)

def process_frame(frame, classifier, scale_factor, min_neighbors, min_size):
    """Processes a single frame to detect and draw faces."""
    gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = detect_faces(gray_frame, classifier, scale_factor, min_neighbors, min_size)
    draw_rectangles(frame, faces, RECTANGLE_COLOR, RECTANGLE_THICKNESS)
    return frame

def main():
    """Main function for real-time face detection."""
    try:
        with open_camera() as camera:
            classifier = load_cascade_classifier(CASCADE_CLASSIFIER_PATH)
            cv2.namedWindow(WINDOW_NAME, cv2.WINDOW_AUTOSIZE)

            while True:
                ret, frame = camera.read()
                if not ret:
                    logging.warning("Failed to grab frame")
                    break

                processed_frame = process_frame(frame, classifier, SCALE_FACTOR, MIN_NEIGHBORS, (30, 30))
                cv2.imshow(WINDOW_NAME, processed_frame)

                if cv2.waitKey(1) & 0xFF == ord(EXIT_KEY):
                    break

    except (KeyboardInterrupt, SystemExit):
        logging.info("Exiting...")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

