import io
import logging
import threading
import time
import traceback
import websocket
from typing import Callable, Optional, Tuple, BinaryIO

import numpy as np
import picamera
from picamera import PiCamera, PiVideoFrameType

from general import WebSocketHandler  # Assuming this module exists

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


def buffer_to_jpeg(buffer: io.BytesIO, quality: int = 85) -> Optional[bytes]:
    """Converts a BytesIO buffer containing raw JPEG data to a byte stream with a specified quality."""
    try:
        buffer.seek(0)
        return picamera.PiCamera()._imencode('.jpg', buffer.read(), quality=quality)[1]
    except Exception as e:
        logging.error(f"Error converting buffer to JPEG: {e}", exc_info=True)
        return None


def detect_motion(previous_frame: Optional[np.ndarray], current_frame: np.ndarray, motion_threshold: float = 25.0) -> bool:
    """Detects motion between two frames using the absolute difference."""
    if previous_frame is None:
        return False
    diff = np.abs(previous_frame.astype(np.int16) - current_frame.astype(np.int16))
    return np.mean(diff) > motion_threshold


class CameraStreamBuffer:
    """A thread-safe buffer for capturing and managing camera frames."""

    def __init__(self, quality: int = 85):
        self._lock = threading.Lock()
        self._buffer: io.BytesIO = io.BytesIO()
        self._quality = quality
        self._event = threading.Event()
        self._first_frame = True

    def wait(self):
        """Waits for a new frame to be available."""
        self._event.wait()

    def get_frame(self) -> Optional[bytes]:
        """Retrieves the latest frame from the buffer as JPEG data."""
        with self._lock:
            self._buffer.seek(0)
            frame = self._buffer.read()
            self._buffer.seek(0)
            self._buffer.truncate()
            self._event.clear()
            return frame if frame else None

    def write(self, data: bytes) -> int:
        """Writes raw frame data to the buffer, handling new frame boundaries and conversion to JPEG."""
        with self._lock:
            try:
                if self._first_frame:
                    if data.startswith(b'\xff\xd8'):
                        self._first_frame = False
                else:
                    if data.startswith(b'\xff\xd8'):
                        frame = buffer_to_jpeg(self._buffer, self._quality)
                        if frame:
                            self._event.set()
                        self._buffer.seek(0)
                        self._buffer.truncate()
                        self._first_frame = True

                self._buffer.write(data)
                return len(data)
            except Exception as e:
                logging.error(f"Error writing to buffer: {e}", exc_info=True)
                return 0


class MotionDetectionBuffer:
    """A buffer for capturing and processing motion detection frames."""

    def __init__(self, motion_callback: Callable[[np.ndarray, np.ndarray], None]):
        self._buffer: io.BytesIO = io.BytesIO()
        self._previous_frame: Optional[np.ndarray] = None
        self._motion_callback: Callable[[np.ndarray, np.ndarray], None] = motion_callback

    def _convert_to_numpy(self, frame_data: bytes) -> Optional[np.ndarray]:
        try:
            # Chances are the frame is a numpy array already
            frame = np.frombuffer(frame_data, dtype=np.uint8)
            return frame.reshape((frame_data.height, frame_data.width, 3), order='C')
        except Exception:
            # Attempt decoding as JPEG in case of unexpected format
            try:
                from skimage import io as skio
                frame = skio.imread(frame_data, as_gray=True, plugin='pil')
                return frame
            except Exception:
                logging.error(f"Could not decode frame: {frame_data[:min(100, len(frame_data))].hex()}")
                return None

    def write(self, data: bytes) -> int:
        """Processes incoming frame data for motion detection."""
        try:
            if data.startswith(b'\xff\xd8'):
                self._buffer.seek(0)
                frame_data = self._buffer.read()
                numpy_frame = self._convert_to_numpy(frame_data)
                if numpy_frame is not None:
                    if detect_motion(self._previous_frame, numpy_frame):
                        self._motion_callback(self._previous_frame, numpy_frame)
                    self._previous_frame = numpy_frame
                self._buffer.seek(0)
                self._buffer.truncate()
            self._buffer.write(data)
            return len(data)
        except Exception as e:
            logging.error(f"Error writing to motion buffer: {e}", exc_info=True)
            return 0


class CameraStream:
    """Streams camera frames over WebSocket with motion detection."""

    def __init__(self, host: str = '0.0.0.0', port: int = 81, quality: int = 64, bitrate: int = 1000000,
                 log_level: str = 'INFO', motion_threshold: float = 25.0):
        self._host = host
        self._port = port
        self._quality = quality
        self._bitrate = bitrate
        self._log_level = log_level
        self._motion_threshold = motion_threshold
        self._camera: Optional[PiCamera] = None
        self._camera_buffer: CameraStreamBuffer = CameraStreamBuffer(self._quality)
        self._motion_buffer: MotionDetectionBuffer = MotionDetectionBuffer(self._camera_buffer.get_frame)
        self._websocket_handler: Optional[WebSocketHandler] = None
        self._websocket_thread: Optional[threading.Thread] = None
        self._running: bool = False

    def _initialize_camera(self) -> bool:
        """Initializes the Raspberry Pi camera."""
        try:
            self._camera = PiCamera()
            self._camera.resolution = (640, 480)
            self._camera.framerate = 10
            self._camera.rotation = 0
            time.sleep(2)  # Allow camera to warm up
            logging.info("Camera initialized successfully.")
            return True
        except picamera.exc.PiCameraError as e:
            logging.error(f"Failed to initialize camera: {e}")
            return False

    def _handle_ws_messages(self, ws: websocket.WebSocket):
        """Handles incoming WebSocket messages."""
        try:
            while self._running:
                message = ws.recv()
                # Process WebSocket messages if needed
                pass
        except websocket.WebSocketException as e:
            logging.error(f"WebSocket error: {e}")
        except Exception as e:
            logging.error(f"Error handling WebSocket messages: {e}", exc_info=True)

    def _stream_loop(self, ws: websocket.WebSocket):
        """Main loop for streaming camera frames over WebSocket."""
        try:
            while self._running:
                frame = self._camera_buffer.get_frame()
                if frame:
                    try:
                        ws.send(frame, websocket.ABNF.OPCODE_BINARY)
                    except websocket.WebSocketException as e:
                        logging.error(f"WebSocket send error: {e}")
                        break  # Exit loop if send fails
                else:
                    time.sleep(0.1)  # Avoid busy-waiting
        except Exception as e:
            logging.error(f"Error in streaming loop: {e}", exc_info=True)
        finally:
            self.stop()

    def _start_websocket_thread(self):
        """Starts the WebSocket handling thread."""
        try:
            self._websocket_handler = WebSocketHandler(self._host, self._port, self._handle_ws_messages)
            self._websocket_thread = threading.Thread(target=self._websocket_handler.run, daemon=True)
            self._websocket_thread.name = "WebSocketThread"
            self._websocket_thread.start()
            logging.info("WebSocket server started in a separate thread.")
        except Exception as e:
            logging.error(f"Failed to start WebSocket server: {e}")

    def start(self):
        """Starts the camera stream process."""
        if self._running:
            logging.warning("Camera stream is already running.")
            return

        if not self._initialize_camera():
            logging.error("Camera initialization failed. Cannot start stream.")
            return

        self._running = True
        self._start_websocket_thread()

        try:
            with self._camera.open_video_stream() as camera_stream:
                while self._running:
                    try:
                        frame = camera_stream.read()
                        if frame.frame_type != PiVideoFrameType.sps_header:
                            self._camera_buffer.write(frame.array.tobytes())
                            self._motion_buffer.write(frame.array.tobytes())
                    except Exception as e:
                        logging.error(f"Error capturing or processing frame: {e}", exc_info=True)
                        time.sleep(0.1)
        except Exception as e:
            logging.error(f"Error in main camera stream loop: {e}", exc_info=True)
        finally:
            self.stop()

    def stop(self):
        """Stops the camera stream and releases resources."""
        if not self._running:
            return

        logging.info("Stopping camera stream...")
        self._running = False

        if self._websocket_handler:
            self._websocket_handler.shutdown()
            self._websocket_thread.join(timeout=5)
            self._websocket_handler = None
            self._websocket_thread = None

        if self._camera:
            self._camera.close()
            self._camera = None

        logging.info("Camera stream stopped.")


if __name__ == '__main__':
    logging.info("Starting camera stream application...")
    camera_stream = CameraStream(port=9090, quality=85, motion_threshold=20.0)
    try:
        camera_stream.start()
        # Add application logic here, e.g., handling WebSocket messages
        while camera_stream._running:
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt detected. Shutting down...")
    finally:
        camera_stream.stop()
        logging.info("Application finished.")

