class CameraStreamBuffer:
    def __init__(self, c, o):
        self.c = c
        self.o = o
        self.b = io.BytesIO()
    def write(self, d):
        self.b.write(d)
        if self.c.f and (self.b.tell() - self.c.p >= self.c.f):
            j = self.b.getvalue()
            self.o.write(j)
            self.b = io.BytesIO()
            self.c.p = 0

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f
        self.p = None
    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            try:
                j = cv2.imdecode(np.frombuffer(d, np.uint8), cv2.IMREAD_COLOR)
                if j is not None:
                    if self.p is not None:
                        self.f(self.p, j)
                    self.p = j
            except:
                pass

