import paho.mqtt.client as mqtt
import json
import time
import random
import threading

# MQTT Broker address
MQTT_BROKER = "test.mosquitto.org"
MQTT_PORT = 1883
MQTT_TOPIC = "classroom/temperature"
READING_COUNT = 5
RETRY_DELAY = 2  # seconds
MAX_RETRIES = 3


def generate_temperature_reading():
    """Generates a simulated temperature reading."""
    return round(random.uniform(19.00, 26.00), 2)


def on_connect(client, userdata, flags, rc):
    """Callback function for MQTT connection."""
    if rc == 0:
        print("Connected to MQTT Broker!")
    else:
        print(f"Failed to connect, return code {rc}")


def on_publish(client, userdata, mid):
    """Callback function for MQTT publish."""
    print(f"Message Published with mid: {mid}")


def publish_temperature(client, reading_index):
    """Publishes a temperature reading to the MQTT broker."""
    temperature = generate_temperature_reading()
    payload = {"temperature": temperature, "timestamp": time.time()}
    message = json.dumps(payload)
    result = client.publish(MQTT_TOPIC, message)
    if result[0] == mqtt.MQTT_ERR_SUCCESS:
        print(f"Published: {message}")
    else:
        print(f"Publish failed with result: {result}")


def main():
    """Main function to publish temperature readings."""
    client = mqtt.Client()
    client.on_connect = on_connect
    client.on_publish = on_publish

    retries = 0
    while retries < MAX_RETRIES:
        try:
            client.connect(MQTT_BROKER, MQTT_PORT, 60)
            break  # Connection successful, exit the loop
        except Exception as e:
            print(f"Connection attempt {retries + 1} failed: {e}")
            retries += 1
            if retries < MAX_RETRIES:
                print(f"Retrying in {RETRY_DELAY} seconds...")
                time.sleep(RETRY_DELAY)
            else:
                print("Max retries reached. Exiting.")
                return  # Exit the main function if connection fails

    if client.is_connected():
        print("Connected to MQTT broker. Starting publishing...")

        for i in range(READING_COUNT):
            publish_temperature(client, i)
            time.sleep(1)  # Wait for 1 second between readings

        print(f"Published {READING_COUNT} messages.")
        client.disconnect()  # Disconnect cleanly
    else:
        print("Not connected to MQTT broker. Exiting.")
        return 1 # Indicate failure

if __name__ == "__main__":
    main()

