# Environmental monitoring script for Raspberry Pi using BME280 and TSL2591 sensors via I2C multiplexer.
# Target: Raspberry Pi 3 Model B+
# Context: Research application

import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initializes the I2C multiplexer."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus)
        return multiplexer
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return None

def initialize_sensors(multiplexer):
    """Initializes the BME280 and TSL2591 sensors."""
    try:
        bme280_sensor = adafruit_bme280.Adafruit_BME280_I2C(multiplexer[0])
        tsl2591_sensor = adafruit_tsl2591.TSL2591(multiplexer[1])
        return bme280_sensor, tsl2591_sensor
    except Exception as e:
        print(f"Error initializing sensors: {e}")
        return None, None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads temperature, humidity, and light intensity from the sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def display_data(temperature, humidity, light_intensity):
    """Prints the sensor data to the console."""
    if temperature is not None and humidity is not None and light_intensity is not None:
        print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light: {light_intensity:.2f} lux")
    else:
        print("Failed to read sensor data.")

def main():
    """Main function to run the environmental monitoring script."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor, tsl2591_sensor = initialize_sensors(multiplexer)
    if bme280_sensor is None or tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            display_data(temperature, humidity, light_intensity)
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for these libraries, but good practice to include a finally block
        print("Program finished.")

if __name__ == "__main__":
    main()

