import serial
import time
import signal
import sys

# Configuration for the weather station UART port
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Global variable to hold the serial port object
serial_connection = None

# Function to handle program termination signals
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for clean exit."""
    print("\nExiting program...")
    if serial_connection:
        serial_connection.close()
    sys.exit(0)

# Register the signal handler for graceful exit
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def read_weather_data():
    """Reads and processes weather data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                temperature, humidity, pressure = map(float, line.split(','))
                if -40 <= temperature <= 85 and 0 <= humidity <= 100 and 800 <= pressure <= 1200:
                    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                    print(f"{timestamp} - Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%, Pressure: {pressure:.1f} hPa")
                else:
                    print(f"Warning: Data out of range: {line}")
            except ValueError:
                print(f"Warning: Invalid data format: {line}")
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to initialize and run the weather station reader."""
    global serial_connection
    try:
        # Initialize the serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to weather station on {SERIAL_PORT}")

        # Main loop to continuously read and process data
        while True:
            read_weather_data()
            time.sleep(1)  # Wait for 1 second before reading again

    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the serial port is closed on exit
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

