import serial
import time
import csv
import os

# Configuration for the UART serial port
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1

# CSV file to store temperature data
CSV_FILE = 'temperature_log.csv'

def initialize_serial(port, baudrate, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_csv(file_path):
    """Initializes the CSV file with a header row if it doesn't exist."""
    if not os.path.exists(file_path):
        try:
