try:
    import RPi.GPIO as GPIO
    dht_available = True
except ImportError:
    GPIO = None
    dht_available = False
try:
    from w1thermsensor import W1ThermSensor, W1ThermSensorError
    ds18b20_available = True
except ImportError:
    W1ThermSensor = None
    ds18b20_available = False

# Configuration
DHT_PIN = 4
STATUS_LED_PIN = 17
LOG_FILE = "hydroponics_data.log"
TEMPERATURE_THRESHOLD_HIGH = 30.0
TEMPERATURE_THRESHOLD_LOW = 25.0
READ_INTERVAL_SECONDS = 5

# Logging setup
logging.basicConfig(filename=LOG_FILE, level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO setup
if GPIO:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(STATUS_LED_PIN, GPIO.OUT)

# Sensor initialization
dht22_sensor = None
ds18b20_sensor = None

if dht_available:
    try:
        import dht
        dht22_sensor = dht.DHT22(DHT_PIN, gpio=GPIO)
    except Exception as e:
        logging.error(f"Failed to initialize DHT22 sensor: {e}")
        dht22_sensor = None

if ds18b20_available:
    try:
        ds18b20_sensor = W1ThermSensor()
    except W1ThermSensorError as e:
        logging.error(f"Failed to initialize DS18B20 sensor: {e}")
        ds18b20_sensor = None

def read_dht22():
    """Reads temperature and humidity from the DHT22 sensor."""
    if dht22_sensor is None:
        return None, None
    try:
        result = dht22_sensor.read()
        temperature = result.temperature
        humidity = result.humidity
        return temperature, humidity
    except Exception as e:
        logging.error(f"Error reading DHT22 sensor: {e}")
        return None, None

def read_ds18b20():
    """Reads temperature from the DS18B20 sensor."""
    if ds18b20_sensor is None:
        return None
    try:
        temperature = ds18b20_sensor.get_temperature()
        return temperature
    except W1ThermSensorError as e:
        logging.error(f"Error reading DS18B20 sensor: {e}")
        return None

def control_status_led(temperature):
    """Controls the status LED based on temperature."""
    if GPIO and temperature is not None:
        if temperature > TEMPERATURE_THRESHOLD_HIGH:
            GPIO.output(STATUS_LED_PIN, GPIO.HIGH)
        elif temperature < TEMPERATURE_THRESHOLD_LOW:
            GPIO.output(STATUS_LED_PIN, GPIO.LOW)

def log_data(temperature, humidity):
    """Logs the temperature and humidity data to the log file."""
    if temperature is not None and humidity is not None:
        logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
    elif temperature is not None:
        logging.info(f"Temperature: {temperature:.2f}°C, Humidity: N/A")
    else:
        logging.info("Temperature: N/A, Humidity: N/A")

def main():
    """Main function to read sensors, log data, and control the status LED."""
    try:
        while True:
            temperature, humidity = read_dht22()
            if temperature is None:
                temperature, _ = read_ds18b20() # Fallback to DS18B20 if DHT22 fails

            log_data(temperature, humidity)
            control_status_led(temperature)

            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        if GPIO:
            GPIO.output(STATUS_LED_PIN, GPIO.LOW)  # Turn off LED on exit
            GPIO.cleanup()
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

