import RPi.GPIO as GPIO
import time
import signal
import sys

# Define the GPIO pins for the sensors
SENSOR_PINS = [17, 27, 22]

# Define the poll interval in seconds
POLL_INTERVAL = 1

# Flag to indicate if the program should exit
running = True

def handle_interrupt(signum, frame):
    """Handles interrupt signals (e.g., Ctrl+C)."""
    global running
    print("Exiting program...")
    running = False

def initialize_gpio(pins):
    """Initializes the GPIO pins as inputs."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in pins:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        print("GPIO initialization complete.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def read_sensor_data(pins):
    """Reads the sensor data from the specified pins."""
    sensor_data = {}
    for i, pin in enumerate(pins):
        try:
            sensor_data[i + 1] = GPIO.input(pin)
        except Exception as e:
            print(f"Error reading sensor {i + 1} on pin {pin}: {e}")
            sensor_data[i + 1] = None  # Indicate an error
    return sensor_data

def process_sensor_data(data):
    """Processes the sensor data and prints responses."""
    for sensor_id, value in data.items():
        if value is not None:
            if sensor_id == 1 and value == GPIO.HIGH:
                print(f"Response for sensor {sensor_id}: Sensor 1 triggered!")
            elif sensor_id == 2 and value == GPIO.HIGH:
                print(f"Response for sensor {sensor_id}: Sensor 2 triggered!")
            elif sensor_id == 3 and value == GPIO.HIGH:
                print(f"Response for sensor {sensor_id}: Sensor 3 triggered!")

def main():
    """Main function to run the sensor monitoring."""
    global running

    # Register the interrupt handler for graceful shutdown
    signal.signal(signal.SIGINT, handle_interrupt)
    signal.signal(signal.SIGTERM, handle_interrupt)

    # Initialize GPIO pins
    initialize_gpio(SENSOR_PINS)

    print(f"Monitoring sensors on pins: {SENSOR_PINS} with a poll interval of {POLL_INTERVAL} seconds.")

    try:
        while running:
            # Read sensor data
            sensor_data = read_sensor_data(SENSOR_PINS)

            # Process and print sensor data
            process_sensor_data(sensor_data)

            # Wait for the specified poll interval
            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        # Clean up GPIO resources
        GPIO.cleanup()
        print("GPIO cleanup complete. Program exiting.")

if __name__ == "__main__":
    main()

