import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom protocol module

# Constants
DEFAULT_LOG_FILE = "data.log"
PROMPT = "JAYES@ROVER53:\t"
RECEIVE_INTERVAL = 0.1  # seconds

# Global State (using a dictionary for immutability within functions)
GLOBAL_STATE = {"is_running": False, "log_file_path": DEFAULT_LOG_FILE, "log_file": None, "receive_thread": None}


def log_message(message):
    """Appends a message to the log file."""
    try:
        if GLOBAL_STATE["log_file"]:
            GLOBAL_STATE["log_file"].write(message + "\n")
            GLOBAL_STATE["log_file"].flush()  # Ensure data is written immediately
    except IOError as e:
        print(f"Error writing to log file: {e}")


def receive_data():
    """Continuously receives data and logs it to the file."""
    while GLOBAL_STATE["is_running"]:
        try:
            data = DOG.receive()
            if data:  # Check if data received is not empty
                log_message(data)
        except Exception as e:
            print(f"Error receiving data: {e}")
            break  # Exit loop on error
        time.sleep(RECEIVE_INTERVAL)


def start_receiving():
    """Starts the receive thread if not already running."""
    if not GLOBAL_STATE["is_running"] and not GLOBAL_STATE["receive_thread"]:
        GLOBAL_STATE["is_running"] = True
        GLOBAL_STATE["receive_thread"] = threading.Thread(target=receive_data, name="ReceiveThread", daemon=True)
        GLOBAL_STATE["receive_thread"].start()
        print("Receiving data...")
    elif GLOBAL_STATE["is_running"]:
        print("Receiving is already running.")
    else:
        print("Another receive operation is in progress.")


def stop_receiving():
    """Stops the receive thread and cleans up."""
    global GLOBAL_STATE  # Access the global state
    GLOBAL_STATE["is_running"] = False
    if GLOBAL_STATE["receive_thread"]:
        GLOBAL_STATE["receive_thread"].join(timeout=1)  # Wait for thread to finish, with timeout
        if GLOBAL_STATE["receive_thread"].is_alive():
            print("Warning: Receive thread did not terminate gracefully.")
        GLOBAL_STATE["receive_thread"] = None
    print("Receiving stopped.")


def send_data(data):
    """Sends data using DOGProtocol."""
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(data):
    """Writes data directly to the log file."""
    try:
        if GLOBAL_STATE["log_file"]:
            GLOBAL_STATE["log_file"].write(data + "\n")
            GLOBAL_STATE["log_file"].flush()
            print(f"Wrote to log: {data}")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def display_log():
    """Displays the contents of the log file."""
    try:
        if GLOBAL_STATE["log_file"]:
            GLOBAL_STATE["log_file"].seek(0)  # Reset file pointer to the beginning
            print(GLOBAL_STATE["log_file"].read())
            GLOBAL_STATE["log_file"].seek(0, 2)  # Move to end of file
        else:
            print("Log file not open.")
    except IOError as e:
        print(f"Error reading log file: {e}")


def help_command(command=None):
    """Displays help information."""
    help_messages = {
