class RotaryEncoder:
    """Rotary encoder driver with callback and debouncing."""

    def __init__(self, clk_pin, dt_pin, callback=None, initial_count=0, debounce_interval=0.005):
        """Initialize the rotary encoder."""
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.current_count = initial_count
        self.previous_clk_state = None
        self.debounce_interval = debounce_interval
        self.event_thread = None

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

            self.previous_clk_state = GPIO.input(self.clk_pin)
            GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self._rotation_detected, bouncetime=int(self.debounce_interval * 1000))
            GPIO.add_event_detect(self.dt_pin, GPIO.BOTH, callback=self._rotation_detected, bouncetime=int(self.debounce_interval * 1000))

        except Exception as e:
            print(f"Error initializing rotary encoder: {e}")
            raise

    def _rotation_detected(self, channel):
        """Handle rotation detection and invoke callback."""
        try:
            clk_state = GPIO.input(self.clk_pin)
            dt_state = GPIO.input(self.dt_pin)

            if clk_state != self.previous_clk_state:
                if dt_state != clk_state:
                    self.current_count += 1
                else:
                    self.current_count -= 1

                self.previous_clk_state = clk_state

                if self.callback:
                    self.callback(self.current_count)

        except Exception as e:
            print(f"Error in rotation callback: {e}")

    def get_count(self):
        """Return the current count."""
        return self.current_count

    def cleanup(self):
        """Clean up GPIO resources."""
        try:
            GPIO.remove_event_detect(self.clk_pin)
            GPIO.remove_event_detect(self.dt_pin)
            GPIO.cleanup()
        except Exception as e:
            print(f"Error cleaning up GPIO: {e}")


def encoder_callback(count):
    """Example callback function."""
    print(f"Encoder count: {count}")


