import serial
import time
import RPi.GPIO as GPIO

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1

# Servo GPIO pin
SERVO_GPIO_PIN = 17

# Function to initialize the serial port
def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial port object."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

# Function to initialize the GPIO pin
def initialize_gpio(pin):
    """Initializes the GPIO pin for PWM output."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    return GPIO.PWM(pin, 50)  # 50Hz PWM frequency

# Function to set the servo angle
def set_servo_angle(pwm_instance, angle):
    """Sets the servo angle based on the given angle value."""
    if 0 <= angle <= 180:
        duty_cycle = 2 + (angle / 18)
        pwm_instance.ChangeDutyCycle(duty_cycle)
        time.sleep(1)  # Hold the position for 1 second
        pwm_instance.ChangeDutyCycle(0)  # Turn off the PWM signal
    else:
        print("Error: Invalid angle. Angle must be between 0 and 180 degrees.")

# Function to read angle data from the serial port
def read_angle_data(serial_port):
    """Reads angle data from the serial port and returns it as an integer."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if data:
            return int(data)
        return None
    except ValueError:
        print("Error: Invalid data received from serial port.")
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

# Main function
def main():
    """Main function to control the servo motor based on serial input."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_connection is None:
        return

    pwm_servo = initialize_gpio(SERVO_GPIO_PIN)

    try:
        pwm_servo.start(0)  # Start PWM with 0% duty cycle
        while True:
            angle_value = read_angle_data(serial_connection)
            if angle_value is not None:
                set_servo_angle(pwm_servo, angle_value)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        pwm_servo.stop()
        GPIO.cleanup()
        serial_connection.close()
        print("GPIO and serial resources cleaned up.")

if __name__ == "__main__":
    main()

