import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins for actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize GPIO settings
GPIO.setmode(GPIO.BCM)
GPIO.setup(PUMP_PIN, GPIO.OUT)
GPIO.setup(LIGHT_PIN, GPIO.OUT)

def parse_intent(phrase):
    """Parses the given phrase and returns the corresponding intent."""
    phrase = phrase.lower()
    if "pump on" in phrase:
        return "pump_on"
    elif "pump off" in phrase:
        return "pump_off"
    elif "light on" in phrase:
        return "light_on"
    elif "light off" in phrase:
        return "light_off"
    elif "toggle light" in phrase:
        return "light_toggle"
    else:
        return "unknown"

def apply_intent(intent):
    """Applies the given intent to the actuators."""
    try:
        if intent == "pump_on":
            GPIO.output(PUMP_PIN, GPIO.HIGH)
            logging.info("Pump turned ON")
        elif intent == "pump_off":
            GPIO.output(PUMP_PIN, GPIO.LOW)
            logging.info("Pump turned OFF")
        elif intent == "light_on":
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            logging.info("Light turned ON")
        elif intent == "light_off":
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            logging.info("Light turned OFF")
        elif intent == "light_toggle":
            current_state = GPIO.input(LIGHT_PIN)
            GPIO.output(LIGHT_PIN, not current_state)
            status = "ON" if not current_state else "OFF"
            logging.info(f"Light toggled to {'ON' if current_state else 'OFF'}")
        else:
            logging.warning(f"Unknown intent: {intent}")
    except Exception as e:
        logging.error(f"Error applying intent: {e}")

def main():
    """Main function to handle voice commands and control actuators."""
    phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    try:
        for phrase in phrases:
            intent = parse_intent(phrase)
            apply_intent(intent)
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

