import RPi.GPIO as GPIO
import time

# Define GPIO pins for the stepper motor driver
MOTOR_PINS = [18, 19, 20, 21]

# Set GPIO numbering mode
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)

# Setup motor pins as output
for pin in MOTOR_PINS:
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)

# Function to perform half-step rotation
def rotate_motor(steps, direction):
    """Rotates the stepper motor a specified number of half-steps in a given direction."""
    for _ in range(steps):
        for halfstep in range(4):
            for pin in range(4):
                GPIO.output(MOTOR_PINS[pin], halfstep & (1 << pin) > 0)
            if direction == 'clockwise':
                halfstep += 1
            else:
                halfstep -= 1
            time.sleep(0.001)

def set_bearing(bearing):
    """Sets the bearing of the motor by rotating it to the specified angle."""
    try:
        bearing = int(bearing)
        if not 0 <= bearing <= 360:
            raise ValueError("Bearing must be between 0 and 360 degrees")

        # Calculate the number of half-steps needed for the rotation
        steps = bearing * 512 / 360

        # Determine rotation direction
        direction = 'clockwise' if bearing > 0 else 'counterclockwise'

        # Rotate the motor
        rotate_motor(int(steps), direction)

        print(f"Motor rotated to {bearing} degrees")
    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def main():
    """Main function to get bearing input and set motor position."""
    try:
        bearing = input("Enter the bearing to set (0-360): ")
        set_bearing(bearing)
    except KeyboardInterrupt:
        print("\nProgram interrupted. Cleaning up...")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

