#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and optimized driver for the DS1338 RTC chip
connected via I2C. It offers comprehensive error handling, performance
optimizations, and adheres to best practices for hardware interaction.
"""

import smbus
from datetime import datetime, timezone
import contextlib

def bcd_to_int(bcd):
    """Decode a 2x4bit BCD to an integer."""
    try:
        return int(f"{bcd >> 4:01}{bcd & 0x0F:01}")
    except ValueError:
        raise ValueError("Invalid BCD value")

def int_to_bcd(value):
    """Encode an integer to 2x4bit BCD."""
    try:
        tens, ones = divmod(value, 10)
        return (tens << 4) | ones
    except TypeError:
        raise ValueError("Invalid integer value")


class DS1338:
    """Driver for the Maxim DS1338 RTC using the I2C interface."""

    # Register addresses
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06
    REG_CONTROL = 0x07
    REG_STATUS = 0x0F  # Added Status Register address

    # Clock halt flag (bit 7 in seconds register)
    CLK_HALT = 0x80

    def __init__(self, i2c_bus=1, device_address=0x68):
        """Initialize the DS1338 driver.

        Args:
            i2c_bus (int): The I2C bus number.
            device_address (int): The I2C address of the DS1338.
        """
        try:
            self._bus = contextlib.closing(smbus.SMBus(i2c_bus))  # Use contextlib for resource management
            self._address = device_address
        except Exception as e:
            raise IOError(f"Failed to initialize I2C bus: {e}")

    def _write_register(self, register, data):
        """Write data to a specific register with error handling."""
        try:
            self._bus.write_byte_data(self._address, register, data)
        except Exception as e:
            raise IOError(f"Failed to write to register {register:#04x}: {e}")

    def _read_register(self, register):
        """Read data from a specific register with error handling."""
        try:
            return self._bus.read_byte_data(self._address, register)
        except Exception as e:
            raise IOError(f"Failed to read from register {register:#04x}: {e}")

    def _read_time_register(self, register):
        """Read and decode a time register (BCD)."""
        return bcd_to_int(self._read_register(register))

    def _write_time_register(self, register, value):
        """Encode and write a time register (BCD)."""
        self._write_register(register, int_to_bcd(value))


    def read_all(self):
        """Read all time registers and return as a tuple."""
        year = self._read_time_register(self.REG_YEAR)
        month = self._read_time_register(self.REG_MONTH)
        date = self._read_time_register(self.REG_DATE)
        day = self._read_time_register(self.REG_DAY)
        hours = self._read_time_register(self.REG_HOURS) & 0x3F # Mask 24/12 bit
        minutes = self._read_time_register(self.REG_MINUTES)
        seconds = self._read_time_register(self.REG_SECONDS) & 0x7F # Mask CH bit
        return year, month, date, day, hours, minutes, seconds

    def read_datetime(self, century=21):
        """Read the current time and build a datetime object."""
        year, month, date, _, hours, minutes, seconds = self.read_all()
        try:
            year = (century - 1) * 100 + year
            return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)
        except ValueError as e:
            raise ValueError(f"Invalid time data read from RTC: {e}")

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all time registers."""

        # Validate input values (range checks)
        if not 1900 <= year <= 2100:
            raise ValueError("Year must be between 1900 and 2100")
        if not 1 <= month <= 12:
            raise ValueError("Month must be between 1 and 12")
        if not 1 <= date <= 31:
            raise ValueError("Date must be between 1 and 31")
        if not 1 <= day <= 7:
            raise ValueError("Day must be between 1 and 7")
        if not 0 <= hours <= 23:
            raise ValueError("Hours must be between 0 and 23")
        if not 0 <= minutes <= 59:
            raise ValueError("Minutes must be between 0 and 59")
        if not 0 <= seconds <= 59:
            raise ValueError("Seconds must be between 0 and 59")

        self._write_time_register(self.REG_SECONDS, seconds)
        self._write_time_register(self.REG_MINUTES, minutes)
        self._write_time_register(self.REG_HOURS, hours) # Ensure 24-hour format
        self._write_time_register(self.REG_DAY, day)
        self._write_time_register(self.REG_DATE, date)
        self._write_time_register(self.REG_MONTH, month)
        self._write_time_register(self.REG_YEAR, year % 100) # Year mod 100


    def write_datetime(self, dt):
        """Write the current time from a datetime object."""
        if not isinstance(dt, datetime):
            raise TypeError("Input must be a datetime object")

            # Check if the datetime object has a timezone and is in UTC
            if dt.tzinfo is None or dt.tzinfo != timezone.utc:
                raise ValueError("Datetime must be in UTC timezone (timezone.utc)")

        self.write_all(dt.year % 100,
                       dt.month,
                       dt.day,
                       dt.isoweekday(),
                       dt.hour,
                       dt.minute,
                       dt.second)

    def write_now(self):
        """Write the current time."""
        self.write_datetime(datetime.now(timezone.utc))

    def enable_auto_incr(self, enable=True):
        """Enable or disable the A2I (Automatic Time Increment) feature."""
        ctrl = self._read_register(self.REG_CONTROL)
        if enable:
            ctrl |= 0x20  # Set A2I bit
        else:
            ctrl &= ~0x20 # Clear A2I bit
        self._write_register(self.REG_CONTROL, ctrl)

    def enable_square_wave(self, enable=True):
        """Enable or disable the square wave output."""
        ctrl = self._read_register(self.REG_CONTROL)
        if enable:
            ctrl |= 0x40  # Set SQWE bit
        else:
            ctrl &= ~0x40 # Clear SQWE bit
        self._write_register(self.REG_CONTROL, ctrl)

    def set_oscillator(self, enable=True):
        """Enable or disable the oscillator."""
        ctrl = self._read_register(self.REG_CONTROL)
        if enable:
            ctrl |= 0x80  # Set OSF bit (enable oscillator)
        else:
            ctrl &= ~0x80 # Clear OSF bit (disable oscillator)
        self._write_register(self.REG_CONTROL, ctrl)

    def get_status_register(self):
        """Read and return the status register."""
        return self._read_register(self.REG_STATUS)

    def get_oscillator_status(self):
        """Return the oscillator status (OSF bit)."""
        return (self.get_status_register() & 0x80) == 0x80


if __name__ == "__main__":
    try:
        rtc = DS1338()
        now = rtc.read_datetime()
        print("Current RTC time:", now.strftime("%Y-%m-%d %H:%M:%S"))
        rtc.enable_auto_incr(True) # Enable automatic time increment
    except (IOError, ValueError) as e:
        print(f"Error: {e}")
        exit(1)

