ALARM_GPIO_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_INTERVAL = 1  # seconds


def initialize_serial(port, baud, timeout):
    """Initializes the serial connection."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def initialize_gpio(pin):
    """Initializes the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)  # Ensure alarm is initially off


def read_radiation_level(serial_connection):
    """Reads a line from the serial port and parses the radiation level."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                return float(line)
            except ValueError:
                print(f"Invalid data received: {line}")
                return None
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def set_alarm_state(pin, radiation_level, threshold):
    """Sets the alarm state based on the radiation level."""
    if radiation_level > threshold:
        GPIO.output(pin, GPIO.HIGH)
        return True
    else:
        GPIO.output(pin, GPIO.LOW)
        return False


def main():
    """Main function to read radiation levels and control the alarm."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        return

    initialize_gpio(ALARM_GPIO_PIN)
    alarm_active = False

    try:
        while True:
            radiation_level = read_radiation_level(serial_connection)

            if radiation_level is not None:
                print(f'Radiation Level: {radiation_level:.2f} µSv/h')

                new_alarm_state = set_alarm_state(ALARM_GPIO_PIN, radiation_level, RADIATION_THRESHOLD)

                if new_alarm_state != alarm_active:
                    if new_alarm_state:
                        print("Alarm: HIGH - Radiation levels exceeded safe threshold!")
                    else:
                        print("Alarm: LOW - Radiation levels are within safe limits.")
                    alarm_active = new_alarm_state

            time.sleep(READ_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up.")


if __name__ == "__main__":
    main()

