import serial
import time
import RPi.GPIO as GPIO

# Serial port configuration for the water flow sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1

# GPIO pin for the flow alarm
ALARM_PIN = 17

# Flow rate threshold for triggering the alarm (L/min)
ALARM_THRESHOLD = 10.0


def configure_serial(port, baud, timeout):
    """Configures and returns a serial port object."""
    return serial.Serial(port, baud, timeout=timeout)


def configure_gpio(pin):
    """Configures the GPIO pin for the alarm."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)


def read_flow_rate(serial_port):
    """Reads and returns the flow rate from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        return None


def trigger_alarm(pin, flow_rate, threshold):
    """Triggers the alarm if the flow rate exceeds the threshold."""
    if flow_rate is not None:
        if flow_rate > threshold:
            GPIO.output(pin, GPIO.HIGH)
            print(f'Flow rate {flow_rate:.2f} L/min exceeds threshold {threshold:.2f} L/min')
        else:
            GPIO.output(pin, GPIO.LOW)


def main():
    """Main function to read flow rate and control the alarm."""
    serial_connection = None
    try:
        serial_connection = configure_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
        configure_gpio(ALARM_PIN)

        while True:
            flow = read_flow_rate(serial_connection)
            if flow is not None:
                print(f'Flow Rate: {flow:.2f} L/min')
                trigger_alarm(ALARM_PIN, flow, ALARM_THRESHOLD)
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")
        GPIO.cleanup()
        print("GPIO resources released.")


if __name__ == "__main__":
    main()

