import json
import time
from datetime import datetime
from threading import Thread
from queue import Queue, Empty
import logging
from logging.handlers import RotatingFileHandler
import serial
from flask import Flask, Response, request, jsonify, abort

# Configure logging
log_formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
log_handler = RotatingFileHandler('inventory.log', maxBytes=1024*1024, backupCount=5)
log_handler.setFormatter(log_formatter)
logger = logging.getLogger(__name__)
logger.setLevel(logging.DEBUG)
logger.addHandler(log_handler)

# Global variables
DATA_QUEUE = Queue()
INVENTORY = [{'id': 1, 'name': 'Item 1', 'done': False}, {'id': 2, 'name': 'Item 2', 'done': True}]
SERIAL_PORT = None  # Initialize to None

# Serial port settings (adjust as needed)
SERIAL_PORT_NAME = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600
SERIAL_TIMEOUT = 1

# Flask app initialization
app = Flask(__name__)

# Serial port management functions
def open_serial_port():
    """Opens the serial port with retry logic."""
    global SERIAL_PORT
    max_retries = 3
    for attempt in range(max_retries):
        try:
            SERIAL_PORT = serial.Serial(SERIAL_PORT_NAME, SERIAL_BAUDRATE, timeout=SERIAL_TIMEOUT)
            logger.info(f"Serial port {SERIAL_PORT_NAME} opened successfully.")
            return True
        except serial.SerialException as e:
            logger.error(f"Failed to open serial port {SERIAL_PORT_NAME}: {e}")
            if attempt < max_retries - 1:
                time.sleep(2**attempt)  # Exponential backoff
            else:
                logger.error("Max serial port open retries reached.  Continuing without serial communication.")
                return False
    return False

def close_serial_port():
    """Closes the serial port."""
    global SERIAL_PORT
    if SERIAL_PORT and SERIAL_PORT.is_open:
        try:
            SERIAL_PORT.close()
            logger.info(f"Serial port {SERIAL_PORT_NAME} closed successfully.")
        except serial.SerialException as e:
            logger.error(f"Failed to close serial port {SERIAL_PORT_NAME}: {e}")

# Inventory data management functions
def get_next_id():
    """Generates the next unique inventory item ID."""
    if not INVENTORY:
        return 1
    return INVENTORY[-1]['id'] + 1

def get_item_by_id(item_id):
    """Retrieves an inventory item by its ID."""
    return next((item for item in INVENTORY if item['id'] == item_id), None)

def get_all_items():
    """Retrieves a list of all inventory items."""
    return INVENTORY

def create_item(name, done):
    """Creates a new inventory item."""
    item_id = get_next_id()
    new_item = {'id': item_id, 'name': name, 'done': done}
    INVENTORY.append(new_item)
    return new_item

def update_item(item_id, name, done):
    """Updates an existing inventory item."""
    item = get_item_by_id(item_id)
    if item:
        item['name'] = name
        item['done'] = done
        return item
    return None

def delete_item(item_id):
    """Deletes an inventory item by its ID."""
    global INVENTORY
    INVENTORY = [item for item in INVENTORY if item['id'] != item_id]

# Web service endpoints
@app.route('/data', methods=['GET'])
def get_all_data():
    """Endpoint to retrieve all inventory items."""
    try:
        data = get_all_items()
        return jsonify(data), 200
    except Exception as e:
        logger.error(f"Error retrieving data: {e}")
        return Response("Internal Server Error", status=500, mimetype='text/plain')

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    """Endpoint to retrieve a specific inventory item by ID."""
    try:
        item = get_item_by_id(item_id)
        if item:
            return jsonify(item), 200
        else:
            return Response("Not Found", status=404, mimetype='text/plain')
    except Exception as e:
        logger.error(f"Error retrieving data for ID {item_id}: {e}")
        return Response("Internal Server Error", status=500, mimetype='text/plain')

@app.route('/data', methods=['POST'])
def create_data():
    """Endpoint to create a new inventory item."""
    try:
        name = request.json.get('name')
        done = request.json.get('done', False)  # Default to False if not provided

        if not name:
            return Response("Name is required", status=400, mimetype='text/plain')

        new_item = create_item(name, done)
        return jsonify(new_item), 201
    except Exception as e:
        logger.error(f"Error creating data: {e}")
        return Response("Bad Request", status=400, mimetype='text/plain')

@app.route('/data/<int:item_id>', methods=['PUT'])
def update_data(item_id):
    """Endpoint to update an existing inventory item."""
    try:
        name = request.json.get('name')
        done = request.json.get('done')

        if not name:
            return Response("Name is required", status=400, mimetype='text/plain')

        item = update_item(item_id, name, done)
        if item:
            return jsonify(item), 200
        else:
            return Response("Not Found", status=404, mimetype='text/plain')
    except Exception as e:
        logger.error(f"Error updating data for ID {item_id}: {e}")
        return Response("Internal Server Error", status=500, mimetype='text/plain')

@app.route('/data/<int:item_id>', methods=['DELETE'])
def delete_data(item_id):
    """Endpoint to delete an inventory item."""
    try:
        delete_item(item_id)
        return Response(status=204)  # No content
    except Exception as e:
        logger.error(f"Error deleting data for ID {item_id}: {e}")
        return Response("Internal Server Error", status=500, mimetype='text/plain')

@app.route('/version', methods=['GET'])
def get_version():
    """Endpoint to retrieve the software version from the serial port."""
    try:
        if SERIAL_PORT and SERIAL_PORT.is_open:
            SERIAL_PORT.write(b"*IDN?\n")
            response = SERIAL_PORT.read(1000)  # Adjust buffer size as needed
            version = response.decode('ascii', errors='replace').strip()  # Handle decoding errors
            return Response(version, mimetype='text/plain')
        else:
            return Response("Serial port not open", status=503, mimetype='text/plain')
    except Exception as e:
        logger.error(f"Error getting version: {e}")
        return Response("Internal Server Error", status=500, mimetype='text/plain')

# Serial communication thread
def serial_communication_thread():
    """Thread to handle serial communication."""
    while True:
        try:
            if SERIAL_PORT and SERIAL_PORT.is_open:
                # Placeholder for serial communication logic
                # This is where you would read data from the serial port
