            else:
                time.sleep(1)
        except Exception as e:
            logger.error(f"Serial communication thread error: {e}")
            break  # Exit the thread on error

# Signal handler (for graceful shutdown)
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logger.info("Received shutdown signal. Closing serial port and exiting...")
    close_serial_port()
    app.shutdown()
    exit(0)

# Main function
def main():
    """Main function to initialize and run the application."""
    try:
        if not open_serial_port():
            logger.warning("Serial port open failed. Continuing without serial communication.")

        # Start the serial communication thread
        serial_thread = Thread(target=serial_communication_thread, daemon=True)
        serial_thread.start()

        # Run the Flask application
        app.run(debug=False, host='0.0.0.0')  # Disable debug in production
    except Exception as e:
