    """Handles signals for graceful shutdown."""
    logger.info("Received shutdown signal. Closing serial port and exiting...")
    close_serial_port()
    app.shutdown()
    exit(0)

# Main function
def main():
    """Main function to initialize and run the application."""
    try:
        if not open_serial_port():
