# smart energy meter reader for Raspberry Pi
# Reads power values from a UART meter and logs them.
import serial
import time
import logging

# Configure logging to a file
logging.basicConfig(filename='power_consumption.log', level=logging.INFO,
                    format='%(asctime)s - Power: %(message)s W')

# UART port configuration
uart_port = '/dev/serial0'
baud_rate = 9600
timeout = 1

def read_power_meter():
    """Reads power data from the UART energy meter."""
    try:
        with serial.Serial(uart_port, baud_rate, timeout=timeout) as ser:
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        try:
                            power_value = float(line)
                            logging.info(str(power_value))
                        except ValueError:
                            logging.error(f"Invalid data received: {line}")
                except serial.SerialException as e:
                    logging.error(f"Serial communication error: {e}")
                    break
                except Exception as e:
                    logging.error(f"An unexpected error occurred: {e}")
                    break
                time.sleep(1)  # Reduced sleep time for responsiveness
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port: {e}")
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        logging.error(f"An unexpected error occurred during initialization: {e}")

if __name__ == "__main__":
    read_power_meter()

