from flask import Flask, Response, request, jsonify
import serial

app = Flask(__name__)
MODEL = 'Web2uart Control'
DATA = [{'id': 1, 'name': 'CHIPS', 'done': False}, {'id': 2, 'name': 'garden', 'done': False}]

def get_instrument():
    """Open and return the serial instrument handle."""
    # Configure the serial port for SCPI communication
    return serial.Serial('/dev/ttyUSB0', 9600, timeout=1)

@app.route('/version', methods=['GET'])
def version():
    """Return the instrument identification string."""
    instr = get_instrument()
    try:
        # Send the *IDN? query and read the response
        instr.write(b'*IDN?\n')
        instr.flush()
        resp = instr.read(100)
        return Response(resp.decode('utf-8').replace('\n', '<br><br>'),
                        mimetype='text/html')
    except Exception as err:
        # Handle any serial communication errors
        print(err)
        return Response(f'<h1>Serial Error: {err}</h1>',
                        mimetype='text/html')
    finally:
        # Always close the serial port
        instr.close()

@app.route('/getdata', methods=['GET'])
def getdata():
    """Return the current to-do list as JSON."""
    return jsonify(DATA)

@app.route('/getset/<int:item_id>', methods=['GET'])
def getset(item_id):
    """Return a specific to-do item as JSON."""
    item = next((item for item in DATA if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    return Response('<h1>Item not found</h1>', mimetype='text/html'), 404

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def getpost(item_id, name):
    """Create a new to-do item and return the updated list."""
    new_id = DATA[-1]['id'] + 1 if DATA else 1
    new_item = {
        'id': new_id,
        'name': name,
        'done': False
    }
    DATA.append(new_item)
    return jsonify(DATA)

@app.route('/postjson', methods=['POST'])
def postjson():
    """Handle JSON data and return the updated list."""
    if 'application/json' in request.headers.get('Content-Type', ''):
        try:
            new_item = request.get_json()
            new_id = DATA[-1]['id'] + 1 if DATA else 1
            new_item['id'] = new_id
            DATA.append(new_item)
            return jsonify(DATA), 201
        except (KeyError, TypeError):
            return Response('<h1>Invalid JSON data</h1>', mimetype='text/html'), 400
    if request.form:
        try:
            new_id = DATA[-1]['id'] + 1 if DATA else 1
            new_item = {
                'id': new_id,
                'name': request.form.get('name', ''),
                'done': request.form.get('done', 'false').lower() == 'true'
            }
            DATA.append(new_item)
            return jsonify(DATA), 201
        except (KeyError, TypeError):
            return Response('<h1>Invalid form data</h1>', mimetype='text/html'), 400
    return Response('<h1>No data received</h1>', mimetype='text/html'), 400

if __name__ == '__main__':
    try:
        # Start the Flask development server in a separate thread
