import serial
import time

# Define the serial port and baud rate
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def send_data_to_uart(serial_connection, data_string):
    """Sends a string of data over the serial connection."""
    try:
        serial_connection.write(data_string.encode())
        print(f"Sent: {data_string}")
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        raise

def receive_data_from_uart(serial_connection):
    """Receives data from the serial port."""
    try:
        received_data = serial_connection.readline().decode('ascii', errors='replace').strip()
        return received_data
    except serial.SerialException as e:
        print(f"Serial communication error: {e}")
        raise

def main():
    """Main function to handle serial communication."""
    serial_connection = None
    try:
        # Initialize serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while True:
            user_input = input("Enter data to send (or 'exit' to quit): ")
            if user_input.lower() == 'exit':
                break

            send_data_to_uart(serial_connection, user_input)
            received_data = receive_data_from_uart(serial_connection)
            if received_data:
                print(f"Received: {received_data}")

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure serial port is closed on exit
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

